class PresenceTracker:
    """在线状态：last_seen 超过 timeout 秒视为离线。ping 刷新 last_seen。"""

    def __init__(self, timeout):
        self.timeout = timeout
        self.last_seen = {}

    def connect(self, uid, now):
        self.last_seen[uid] = now

    def ping(self, uid, now):
        pass

    def is_offline(self, uid, now):
        return now - self.last_seen[uid] > self.timeout
